UNITS = [
 {"id": "PEDS-U349", "ch": 44, "n": 1, "title": "Adrenal Physiology — Steroidogenesis", "sec": "Adrenal physiology and steroidogenesis · p204", "qs": ["PEDS-C44-001", "PEDS-C44-002", "PEDS-C44-003", "PEDS-C44-004", "PEDS-C44-005", "PEDS-C44-006", "PEDS-C44-007", "PEDS-C44-008", "PEDS-C44-009", "PEDS-C44-010", "PEDS-C44-011", "PEDS-C44-012", "PEDS-C44-013", "PEDS-C44-014", "PEDS-C44-015", "PEDS-C44-016", "PEDS-C44-017", "PEDS-C44-018"], "guide": "All adrenal steroids derive from cholesterol. Glucocorticoid synthesis is ACTH-regulated; aldosterone is regulated by intravascular volume, plasma K+ and RAAS. StAR (steroidogenic acute regulatory protein) shuttles cholesterol into mitochondria."},
 {"id": "PEDS-U350", "ch": 44, "n": 2, "title": "Cushing Syndrome — Etiology", "sec": "Cushing syndrome etiology · p204", "qs": ["PEDS-C44-019", "PEDS-C44-020", "PEDS-C44-021", "PEDS-C44-022", "PEDS-C44-023", "PEDS-C44-024", "PEDS-C44-025", "PEDS-C44-026", "PEDS-C44-027", "PEDS-C44-028", "PEDS-C44-029", "PEDS-C44-030", "PEDS-C44-031", "PEDS-C44-032", "PEDS-C44-033", "PEDS-C44-034", "PEDS-C44-035", "PEDS-C44-036", "PEDS-C44-037"], "guide": "Cushing syndrome = excess glucocorticoids; the m/c cause overall is exogenous steroid therapy. Endogenous disease is ACTH-independent (adrenal adenoma/carcinoma, young children) or ACTH-dependent (pituitary microadenoma = Cushing disease; ectopic ACTH from neuroblastoma, Wilms tumour, carcinoid)."},
 {"id": "PEDS-U351", "ch": 44, "n": 3, "title": "Cushing Syndrome — Clinical Features", "sec": "Cushing syndrome clinical features · p204–205", "qs": ["PEDS-C44-038", "PEDS-C44-039", "PEDS-C44-040", "PEDS-C44-041", "PEDS-C44-042", "PEDS-C44-043", "PEDS-C44-044", "PEDS-C44-045", "PEDS-C44-046", "PEDS-C44-047", "PEDS-C44-048", "PEDS-C44-049", "PEDS-C44-050", "PEDS-C44-051", "PEDS-C44-052", "PEDS-C44-053", "PEDS-C44-054", "PEDS-C44-055"], "guide": "Glucocorticoid excess blocks lipolysis → fat deposition: moon facies, abdominal obesity, striae and buffalo hump. Hypertension (intrinsic mineralocorticoid activity), hirsutism (ACTH-driven androgens), delayed puberty (cortisol inhibits gonadotropins), proximal muscle weakness and short stature."},
 {"id": "PEDS-U352", "ch": 44, "n": 4, "title": "Cushing Syndrome — Investigations & Treatment", "sec": "Cushing investigations and treatment · p205–206", "qs": ["PEDS-C44-056", "PEDS-C44-057", "PEDS-C44-058", "PEDS-C44-059", "PEDS-C44-060", "PEDS-C44-061", "PEDS-C44-062", "PEDS-C44-063", "PEDS-C44-064", "PEDS-C44-065", "PEDS-C44-066", "PEDS-C44-067", "PEDS-C44-068", "PEDS-C44-069", "PEDS-C44-070", "PEDS-C44-071", "PEDS-C44-072", "PEDS-C44-073", "PEDS-C44-074", "PEDS-C44-075", "PEDS-C44-076", "PEDS-C44-077", "PEDS-C44-078", "PEDS-C44-079"], "guide": "Screen with 24-hour urine free cortisol and the overnight dexamethasone suppression test; confirm with low-dose DST (5 μg/kg q6H × 2 days). ACTH level separates ACTH-independent (<15 pg/mL) from pituitary (>15) and ectopic (>100); high-dose DST confirms pituitary suppressibility. Treat by tumour resection, trans-sphenoidal surgery, or medical adrenalectomy."},
 {"id": "PEDS-U353", "ch": 44, "n": 5, "title": "Congenital Adrenal Hyperplasia — Basis & Pathophysiology", "sec": "CAH basis and pathophysiology · p206", "qs": ["PEDS-C44-080", "PEDS-C44-081", "PEDS-C44-082", "PEDS-C44-083", "PEDS-C44-084", "PEDS-C44-085", "PEDS-C44-086", "PEDS-C44-087", "PEDS-C44-088", "PEDS-C44-089", "PEDS-C44-090", "PEDS-C44-091", "PEDS-C44-092", "PEDS-C44-093", "PEDS-C44-094", "PEDS-C44-095", "PEDS-C44-096", "PEDS-C44-097", "PEDS-C44-098"], "guide": "CAH is the m/c adrenal disorder of childhood, autosomal recessive. Enzyme blockade lowers glucocorticoids → loss of feedback → ↑ACTH → tropic stimulation → adrenal hyperplasia with shunting of precursors. 21-hydroxylase deficiency is the m/c form; 11-β-OH and 17-α-OH are the other classics."},
 {"id": "PEDS-U354", "ch": 44, "n": 6, "title": "21-Hydroxylase Deficiency", "sec": "21-hydroxylase deficiency · p207", "qs": ["PEDS-C44-099", "PEDS-C44-100", "PEDS-C44-101", "PEDS-C44-102", "PEDS-C44-103", "PEDS-C44-104", "PEDS-C44-105", "PEDS-C44-106", "PEDS-C44-107", "PEDS-C44-108", "PEDS-C44-109", "PEDS-C44-110", "PEDS-C44-111", "PEDS-C44-112", "PEDS-C44-113", "PEDS-C44-114", "PEDS-C44-115", "PEDS-C44-116", "PEDS-C44-117", "PEDS-C44-118", "PEDS-C44-119", "PEDS-C44-120", "PEDS-C44-121"], "guide": "21-OH deficiency blocks aldosterone and cortisol → salt wasting (hyponatremia, shock, hyperkalemia) with androgen excess (precocious puberty in males, ambiguous genitalia in females) and ACTH-driven hyperpigmentation. Screen with 17-OHP; replace hydrocortisone + fludrocortisone lifelong with stress dosing."},
 {"id": "PEDS-U355", "ch": 44, "n": 7, "title": "11-β-Hydroxylase Deficiency", "sec": "11-β-hydroxylase deficiency · p207", "qs": ["PEDS-C44-122", "PEDS-C44-123", "PEDS-C44-124", "PEDS-C44-125", "PEDS-C44-126", "PEDS-C44-127", "PEDS-C44-128", "PEDS-C44-129", "PEDS-C44-130", "PEDS-C44-131", "PEDS-C44-132", "PEDS-C44-133", "PEDS-C44-134", "PEDS-C44-135"], "guide": "11-β-OH deficiency piles up 11-deoxycorticosterone — a mineralocorticoid — so the child is hypertensive despite low aldosterone, with androgen excess (virilisation/precocious puberty) and ACTH-mediated hyperpigmentation."},
 {"id": "PEDS-U356", "ch": 44, "n": 8, "title": "17-α-Hydroxylase & 3-β-HSD Deficiency + Diagnostic Pointers", "sec": "17-α-OH, 3-β-HSD deficiency and diagnostic pointers · p208", "qs": ["PEDS-C44-136", "PEDS-C44-137", "PEDS-C44-138", "PEDS-C44-139", "PEDS-C44-140", "PEDS-C44-141", "PEDS-C44-142", "PEDS-C44-143", "PEDS-C44-144", "PEDS-C44-145", "PEDS-C44-146", "PEDS-C44-147", "PEDS-C44-148", "PEDS-C44-149", "PEDS-C44-150", "PEDS-C44-151", "PEDS-C44-152", "PEDS-C44-153", "PEDS-C44-154", "PEDS-C44-155", "PEDS-C44-156", "PEDS-C44-157", "PEDS-C44-158", "PEDS-C44-159", "PEDS-C44-160", "PEDS-C44-161", "PEDS-C44-162"], "guide": "17-α-OH deficiency: hypertension with undervirilised males and delayed puberty (low androgens). 3-β-HSD deficiency: salt wasting with undervirilised males and mildly virilised females (DHEA). Pointers: salt wasting + high androgen → 21-OH; salt wasting + low androgen → 3-β-HSD; HTN + high androgen → 11-β-OH; HTN + low androgen → 17-α-OH."},
]

