 {"id": "PEDS-C44-047", "sec": "Cushing syndrome clinical features", "page": 205, "q": "Short stature in Cushing syndrome reflects —", "opts": ["Early epiphyseal fusion", "Vertebral collapse only", "Malabsorption", "Slowing of growth"], "ans": 3, "exp": "Short stature: slowing of growth. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-048", "sec": "Cushing syndrome clinical features", "page": 205, "q": "A 13-year-old on long-term prednisolone has moon facies, abdominal obesity, purple striae over the flanks, a dorsocervical fat pad and blood pressure 138/92 mmHg. The hypertension is due to —", "opts": ["Intrinsic mineralocorticoid activity of glucocorticoids", "Renin-secreting tumour", "Coarctation of aorta", "Phaeochromocytoma"], "ans": 0, "exp": "Cushing syndrome HTN = intrinsic mineralocorticoid activity of some glucocorticoids. (Book p205)", "type": "case", "stem": "A 13-year-old on long-term prednisolone for nephrotic syndrome has moon facies, central obesity, purple striae, buffalo hump and BP 138/92 mmHg."},
 {"id": "PEDS-C44-049", "sec": "Cushing syndrome clinical features", "page": 205, "q": "Match the Cushing feature with its mechanism:", "opts": ["A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2", "A-1, B-3, C-4, D-2", "A-3, B-4, C-1, D-2"], "ans": 1, "exp": "Correct pairs: Fat deposition→Blocked lipolysis; Hypertension→Intrinsic mineralocorticoid activity; Hirsutism→ACTH-driven androgen excess; Delayed puberty→Cortisol inhibits gonadotropins. (Book p204–205)", "type": "match", "pairs": [["Fat deposition", "Intrinsic mineralocorticoid activity"], ["Hypertension", "Blocked lipolysis"], ["Hirsutism", "Cortisol inhibits gonadotropins"], ["Delayed puberty", "ACTH-driven androgen excess"]]},
 {"id": "PEDS-C44-050", "sec": "Cushing syndrome clinical features", "page": 205, "q": "Which Cushing feature points specifically to an ACTH-dependent cause?", "opts": ["Striae", "Buffalo hump", "Hirsutism", "Moon facies"], "ans": 2, "exp": "Hirsutism occurs in ACTH-dependent conditions (adrenal androgen overstimulation). (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-051", "sec": "Cushing syndrome clinical features", "page": 205, "q": "Odd one out (clinical features of Cushing syndrome):", "opts": ["Moon facies", "Proximal muscle weakness", "Buffalo hump", "Hyperpigmentation of skin creases"], "ans": 3, "exp": "Hyperpigmentation belongs to ACTH-driven conditions like CAH (MSH-receptor action); the other three are listed Cushing features. (Book p205, 207)", "type": "odd"},
 {"id": "PEDS-C44-052", "sec": "Cushing syndrome clinical features", "page": 205, "q": "Cushing syndrome causes growth acceleration in children.", "opts": ["True", "False"], "ans": 1, "exp": "False — Short stature d/t slowing of growth. (Book p205)", "type": "tf"},
 {"id": "PEDS-C44-053", "sec": "Cushing syndrome clinical features", "page": 205, "q": "Striae in Cushing syndrome arise from excessive stretching of the skin.", "opts": ["True", "False"], "ans": 0, "exp": "True — Striae d/t excessive stretching of skin. (Book p205)", "type": "tf"},
 {"id": "PEDS-C44-054", "sec": "Cushing syndrome clinical features", "page": 205, "q": "The muscle weakness of pediatric Cushing syndrome is distal.", "opts": ["True", "False"], "ans": 1, "exp": "False — Proximal muscle weakness (shoulders, hip). (Book p205)", "type": "tf"},
 {"id": "PEDS-C44-055", "sec": "Cushing syndrome clinical features", "page": 205, "q": "In Cushing syndrome, fat deposition is the direct result of glucocorticoid-blocked ___.", "opts": ["Lipogenesis", "Glycolysis", "Proteolysis", "Lipolysis"], "ans": 3, "exp": "Glucocorticoids block lipolysis → fat deposition. (Book p204)", "type": "fill"},
 {"id": "PEDS-C44-056", "sec": "Cushing investigations and treatment", "page": 205, "q": "Screening investigations for Cushing syndrome include 24-hour urine free cortisol and —", "opts": ["Overnight dexamethasone suppression test", "Random plasma cortisol", "Serum ACTH alone", "Adrenal CT"], "ans": 0, "exp": "Screening: 24h urine free cortisol levels; overnight dexamethasone suppression test. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-057", "sec": "Cushing investigations and treatment", "page": 205, "q": "Overnight dexamethasone suppression test involves a single dexamethasone dose given at —", "opts": ["Any random time", "Night", "Dawn", "Noon"], "ans": 1, "exp": "Single dose dexamethasone at night; cortisol checked next morning. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-058", "sec": "Cushing investigations and treatment", "page": 205, "q": "A NORMAL response to overnight dexamethasone is —", "opts": ["No change in cortisol", "Increased ACTH", "Decreased cortisol next morning", "Increased cortisol next morning"], "ans": 2, "exp": "Normal: decreased cortisol in morning d/t suppression by dexamethasone. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-059", "sec": "Cushing investigations and treatment", "page": 205, "q": "In Cushing syndrome the overnight dexamethasone test shows —", "opts": ["Decreased cortisol next morning", "Suppressed ACTH only", "Normal cortisol rhythm", "Increased cortisol next morning (unable to suppress)"], "ans": 3, "exp": "Cushing syndrome: increased cortisol levels next morning (unable to suppress). (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-060", "sec": "Cushing investigations and treatment", "page": 205, "q": "A child fails to suppress cortisol after an overnight dexamethasone dose. The report reads —", "opts": ["Suggestive of Cushing syndrome", "Rule out Cushing syndrome", "Suggests adrenal insufficiency", "Suggests pseudo-Cushing"], "ans": 0, "exp": "Failure of overnight suppression = increased next-morning cortisol = Cushing syndrome screen positive. (Book p205)", "type": "case", "stem": "A 12-year-old with central obesity, striae and hypertension is given a single night-time dexamethasone dose; the 8 a.m. cortisol remains high."},
 {"id": "PEDS-C44-061", "sec": "Cushing investigations and treatment", "page": 205, "q": "The diagnostic (confirmatory) test for Cushing syndrome is the —", "opts": ["ACTH stimulation test", "Low-dose dexamethasone suppression test", "Overnight suppression test alone", "Random cortisol"], "ans": 1, "exp": "Diagnosis: low-dose dexamethasone suppression test. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-062", "sec": "Cushing investigations and treatment", "page": 205, "q": "Low-dose dexamethasone suppression test uses dexamethasone ___ q6H × 2 days.", "opts": ["5 μg/kg", "5 mg/kg", "50 μg/kg", "0.5 μg/kg"], "ans": 2, "exp": "Low-dose DST: 5 μg/kg of dexamethasone q6H × 2 days. (Book p205)", "type": "fill"},
 {"id": "PEDS-C44-063", "sec": "Cushing investigations and treatment", "page": 205, "q": "After low-dose DST, a cortisol level that remains high indicates —", "opts": ["Normal suppression", "Addison disease", "Isolated obesity", "Cushing syndrome"], "ans": 3, "exp": "Low-dose DST in Cushing syndrome: increased cortisol level (no suppression). (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-064", "sec": "Cushing investigations and treatment", "page": 205, "q": "ACTH estimation after confirming Cushing syndrome is used to —", "opts": ["Differentiate ACTH-dependent from independent disease", "Confirm the diagnosis of Cushing", "Localise the adrenal tumour", "Assess glucocorticoid reserve"], "ans": 0, "exp": "ACTH estimation (pg/mL) differentiates based on ACTH dependence. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-065", "sec": "Cushing investigations and treatment", "page": 205, "q": "ACTH below ___ pg/mL indicates ACTH-independent Cushing syndrome.", "opts": ["5", "15", "40", "100"], "ans": 1, "exp": "Low ACTH (ACTH-independent) < 15 pg/mL. (Book p205)", "type": "fill"},
 {"id": "PEDS-C44-066", "sec": "Cushing investigations and treatment", "page": 205, "q": "ACTH above 15 pg/mL in Cushing syndrome indicates —", "opts": ["Adrenal carcinoma", "Exogenous steroids", "Pituitary source", "Adrenal adenoma"], "ans": 2, "exp": "High ACTH (pituitary source) > 15 pg/mL. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-067", "sec": "Cushing investigations and treatment", "page": 205, "q": "ACTH above 100 pg/mL in Cushing syndrome suggests —", "opts": ["Pituitary microadenoma", "Adrenal adenoma", "Hypothalamic CRH excess", "Ectopic tumour releasing ACTH"], "ans": 3, "exp": "Very high ACTH (> 100 pg/mL): ectopic tumour releasing ACTH. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-068", "sec": "Cushing investigations and treatment", "page": 205, "q": "High-dose dexamethasone suppression test is used to —", "opts": ["Distinguish pituitary from ectopic ACTH source", "Screen for Cushing syndrome", "Confirm adrenal insufficiency", "Assess striae severity"], "ans": 0, "exp": "High-dose DST: suppression points to pituitary source; no suppression points to ectopic ACTH. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-069", "sec": "Cushing investigations and treatment", "page": 205, "q": "Cortisol that SUPPRESSES with high-dose dexamethasone indicates —", "opts": ["Exogenous cause", "Pituitary source", "Ectopic ACTH source", "Adrenal carcinoma"], "ans": 1, "exp": "Suppression on high-dose DST = pituitary source (Cushing disease); ectopic tumours do not suppress. (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-070", "sec": "Cushing investigations and treatment", "page": 205, "q": "A child with Cushing syndrome has ACTH 220 pg/mL and no suppression on high-dose DST. Source —", "opts": ["Adrenal adenoma", "Exogenous steroid", "Ectopic ACTH tumour", "Pituitary microadenoma"], "ans": 2, "exp": "Very high ACTH (> 100 pg/mL) + no high-dose suppression = ectopic ACTH release (e.g., neuroblastoma). (Book p205)", "type": "case", "stem": "An 8-year-old with Cushing syndrome has ACTH 220 pg/mL; cortisol fails to suppress on high-dose dexamethasone. Abdominal imaging shows an adrenal mass."},
 {"id": "PEDS-C44-071", "sec": "Cushing investigations and treatment", "page": 205, "q": "Match the Cushing work-up step with its purpose:", "opts": ["A-1, B-3, C-4, D-2", "A-3, B-4, C-1, D-2", "A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2"], "ans": 3, "exp": "Correct pairs: 24h urine free cortisol→Screening; Overnight DST→Screening; Low-dose DST→Diagnosis; High-dose DST→Pituitary vs ectopic. (Book p205)", "type": "match", "pairs": [["24h urine free cortisol", "Screening"], ["Overnight DST", "Pituitary vs ectopic"], ["Low-dose DST", "Screening"], ["High-dose DST", "Diagnosis"]]},
 {"id": "PEDS-C44-072", "sec": "Cushing investigations and treatment", "page": 206, "q": "Surgical treatment of Cushing syndrome due to an identified tumour is —", "opts": ["Resection of the tumour", "Bilateral adrenalectomy always", "Radiotherapy first", "Medical therapy alone"], "ans": 0, "exp": "Surgical: resection of identified tumour. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-073", "sec": "Cushing investigations and treatment", "page": 206, "q": "Surgery for Cushing disease (pituitary microadenoma) is —", "opts": ["Adrenalectomy", "Trans-sphenoidal resection", "Trans-frontal craniotomy", "Stereotactic radiosurgery"], "ans": 1, "exp": "Cushing's disease: trans-sphenoidal resection. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-074", "sec": "Cushing investigations and treatment", "page": 206, "q": "Medical therapy of Cushing syndrome is also known as —", "opts": ["Chemical sympathectomy", "Pseudoadrenal blockade", "Medical adrenalectomy", "Medical hypophysectomy"], "ans": 2, "exp": "Medical: AKA medical adrenalectomy. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-075", "sec": "Cushing investigations and treatment", "page": 206, "q": "Medical adrenalectomy inhibits adrenal steroidogenesis using —", "opts": ["Anti-hypertensives", "Anti-androgens", "Bisphosphonates", "Anti-fungals"], "ans": 3, "exp": "Medical inhibition of adrenal steroidogenesis by anti-fungals. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-076", "sec": "Cushing investigations and treatment", "page": 206, "q": "Drugs used for medical adrenalectomy include ketoconazole, metyrapone and —", "opts": ["Mitotane", "Metyrosine", "Spironolactone", "Aminoglutethimide only"], "ans": 0, "exp": "Anti-fungals listed: ketoconazole, metyrapone, mitotane. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-077", "sec": "Cushing investigations and treatment", "page": 206, "q": "Which drug used in Cushing syndrome is an anti-fungal that blocks steroidogenesis?", "opts": ["Fluconazole", "Ketoconazole", "Ketamine", "Ketoconazole and ketamine both"], "ans": 1, "exp": "Ketoconazole (anti-fungal) inhibits adrenal steroidogenesis; listed with metyrapone and mitotane. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-078", "sec": "Cushing investigations and treatment", "page": 206, "q": "In overnight DST, a normal person suppresses cortisol through feedback on the —", "opts": ["Kidney", "Liver metabolism only", "Pituitary-hypothalamic axis", "Adrenal medulla"], "ans": 2, "exp": "Normal: decreased morning cortisol d/t suppression by dexamethasone (pituitary suppression). (Book p205)", "type": "mcq"},
 {"id": "PEDS-C44-079", "sec": "Cushing investigations and treatment", "page": 206, "q": "Odd one out (medical management of Cushing syndrome):", "opts": ["Ketoconazole", "Metyrapone", "Mitotane", "Methimazole"], "ans": 3, "exp": "Methimazole is an antithyroid drug; ketoconazole, metyrapone and mitotane inhibit adrenal steroidogenesis. (Book p206)", "type": "odd"},
 {"id": "PEDS-C44-080", "sec": "CAH basis and pathophysiology", "page": 206, "q": "The most common adrenal disorder in childhood is —", "opts": ["Congenital adrenal hyperplasia", "Addison disease", "Neuroblastoma", "Pheochromocytoma"], "ans": 0, "exp": "CAH: m/c adrenal disorder in childhood. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-081", "sec": "CAH basis and pathophysiology", "page": 206, "q": "Mode of inheritance of congenital adrenal hyperplasia is —", "opts": ["Mitochondrial", "Autosomal recessive", "Autosomal dominant", "X-linked recessive"], "ans": 1, "exp": "CAH: autosomal recessive inheritance. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-082", "sec": "CAH basis and pathophysiology", "page": 206, "q": "In CAH the primary biochemical defect is —", "opts": ["ACTH receptor defect", "Cholesterol deficiency", "Enzyme deficiency in steroidogenesis", "Adrenal hypoplasia"], "ans": 2, "exp": "Decreased enzyme → decreased steroids (glucocorticoid). (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-083", "sec": "CAH basis and pathophysiology", "page": 206, "q": "The hormone that is directly decreased by the enzyme block in CAH is —", "opts": ["ACTH", "Androgens always", "Aldosterone always", "Glucocorticoid"], "ans": 3, "exp": "The block lowers steroids — glucocorticoid (the feedback hormone). (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-084", "sec": "CAH basis and pathophysiology", "page": 206, "q": "Decreased glucocorticoid in CAH leads to increased secretion of —", "opts": ["ACTH", "Cortisol", "Aldosterone", "Somatostatin"], "ans": 0, "exp": "Decreased glucocorticoid → feedback to pituitary gland → increased ACTH. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-085", "sec": "CAH basis and pathophysiology", "page": 206, "q": "The trophic effect of chronically raised ACTH on the adrenal gland produces —", "opts": ["Adrenal haemorrhage", "Adrenal hyperplasia", "Adrenal atrophy", "Adrenal calcification"], "ans": 1, "exp": "Increased ACTH → tropic action → cholesterol desmolase drive → adrenal gland hyperplasia. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-086", "sec": "CAH basis and pathophysiology", "page": 206, "q": "ACTH raises adrenal steroid output by stimulating which enzyme?", "opts": ["5α-reductase", "Aldosterone synthase", "Cholesterol desmolase", "Aromatase"], "ans": 2, "exp": "ACTH tropic action drives cholesterol → cholesterol desmolase → steroidogenesis. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-087", "sec": "CAH basis and pathophysiology", "page": 206, "q": "The m/c enzyme deficiency in CAH is —", "opts": ["11-β-hydroxylase", "17-α-hydroxylase", "3-β-HSD", "21-hydroxylase"], "ans": 3, "exp": "Deficiency of enzymes: 21-hydroxylase (21-OH) — most common. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-088", "sec": "CAH basis and pathophysiology", "page": 206, "q": "Enzyme deficiencies causing CAH include 21-OH, 11-β-OH and —", "opts": ["17-α-OH", "5α-reductase", "Aromatase", "Aldosterone synthase"], "ans": 0, "exp": "Listed deficiencies: 21-hydroxylase, 11-β-hydroxylase, 17-α-hydroxylase. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-089", "sec": "CAH basis and pathophysiology", "page": 206, "q": "In the steroidogenesis pathway, 21-hydroxylase converts progesterone to 11-deoxycorticosterone and 17-hydroxyprogesterone to —", "opts": ["Aldosterone", "11-deoxycortisol", "Corticosterone", "Androstenedione"], "ans": 1, "exp": "17-hydroxyprogesterone → (21-OH) → 11-deoxycortisol → (11-β-OH) → cortisol. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-090", "sec": "CAH basis and pathophysiology", "page": 206, "q": "Cortisol is synthesized from 11-deoxycortisol by the enzyme —", "opts": ["17-α-hydroxylase", "3-β-HSD", "11-β-hydroxylase", "21-hydroxylase"], "ans": 2, "exp": "11-deoxycortisol → (11-β-hydroxylase) → cortisol. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-091", "sec": "CAH basis and pathophysiology", "page": 206, "q": "17-hydroxylase and 17,20-lyase activities in steroidogenesis relate to the —", "opts": ["C21 enzyme", "C11 enzyme", "C18 enzyme", "C17/C20 enzyme (CYP17)"], "ans": 3, "exp": "The pathway shows 17-α-hydroxylase and 17,20-lyase acting on pregnenolone/progesterone toward androgens. (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-092", "sec": "CAH basis and pathophysiology", "page": 206, "q": "Adrenal androgen synthesis shunts pregnenolone toward —", "opts": ["Dehydroepiandrosterone (DHEA)", "Cortisol", "Aldosterone", "Estradiol directly"], "ans": 0, "exp": "17-hydroxypregnenolone → (17,20-lyase) → dehydroepiandrosterone (androgen pathway). (Book p206)", "type": "mcq"},
 {"id": "PEDS-C44-093", "sec": "CAH basis and pathophysiology", "page": 206, "q": "A newborn with ambiguous genitalia, hyponatremia and hyperkalemia has an enzyme block in the pathway toward cortisol. The enlarged adrenals result from —", "opts": ["Compensatory Renin excess", "ACTH trophic action", "Congenital hyperplasia of the medulla", "Adrenal haemorrhage"], "ans": 1, "exp": "Decreased enzyme → ↓ glucocorticoid → ↑ ACTH (feedback) → tropic action → adrenal hyperplasia = CAH. (Book p206)", "type": "case", "stem": "A 12-day-old 46,XX infant has clitoromegaly with fused labia, hyponatremia, hyperkalemia and shock. ACTH is markedly elevated and both adrenals are enlarged."},
 {"id": "PEDS-C44-094", "sec": "CAH basis and pathophysiology", "page": 206, "q": "Match the enzyme with its substrate in the mineralocorticoid pathway:", "opts": ["A-3, B-4, C-1, D-2", "A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2", "A-1, B-3, C-4, D-2"], "ans": 2, "exp": "Correct pairs: Cholesterol desmolase→Cholesterol; 21-OH→Progesterone; Aldosterone synthase→Corticosterone; 11-β-OH→11-deoxycortisol. (Book p206)", "type": "match", "pairs": [["Cholesterol desmolase", "Progesterone"], ["21-OH", "Corticosterone"], ["Aldosterone synthase", "Cholesterol"], ["11-β-OH", "11-deoxycortisol"]]},
 {"id": "PEDS-C44-095", "sec": "CAH basis and pathophysiology", "page": 206, "q": "CAH follows X-linked recessive inheritance.", "opts": ["True", "False"], "ans": 1, "exp": "False — CAH is autosomal recessive. (Book p206)", "type": "tf"},
 {"id": "PEDS-C44-096", "sec": "CAH basis and pathophysiology", "page": 206, "q": "The hyperplasia in CAH is caused by loss of glucocorticoid feedback with ACTH excess.", "opts": ["True", "False"], "ans": 0, "exp": "True — ↓ glucocorticoid → ↑ ACTH → trophic action → adrenal hyperplasia. (Book p206)", "type": "tf"},
 {"id": "PEDS-C44-097", "sec": "CAH basis and pathophysiology", "page": 206, "q": "The most common form of CAH worldwide is 11-β-hydroxylase deficiency.", "opts": ["True", "False"], "ans": 1, "exp": "False — 21-hydroxylase deficiency is the most common. (Book p206)", "type": "tf"},
 {"id": "PEDS-C44-098", "sec": "CAH basis and pathophysiology", "page": 206, "q": "In CAH the decreased steroid that triggers the feedback loop is the ___.", "opts": ["Androgen", "Catecholamine", "Glucocorticoid", "Mineralocorticoid"], "ans": 2, "exp": "Decreased enzyme → decreased steroids (glucocorticoid) → feedback → increased ACTH. (Book p206)", "type": "fill"},
 {"id": "PEDS-C44-099", "sec": "21-hydroxylase deficiency", "page": 207, "q": "In 21-hydroxylase deficiency, the hormones distal to the block that DECREASE are —", "opts": ["Cortisol and androgens", "Aldosterone and androgens", "ACTH and cortisol", "Aldosterone and cortisol"], "ans": 3, "exp": "Decreased enzyme → decreased aldosterone + decreased cortisol (with increased ACTH → increased increased androgens). (Book p207)", "type": "mcq"},
 {"id": "PEDS-C44-100", "sec": "21-hydroxylase deficiency", "page": 207, "q": "In 21-OH deficiency the accumulated precursors are shunted toward —", "opts": ["Androgen synthesis", "Aldosterone synthesis", "Estradiol synthesis", "Catecholamine synthesis"], "ans": 0, "exp": "Increased ACTH → markedly increased androgens. (Book p207)", "type": "mcq"},
 {"id": "PEDS-C44-101", "sec": "21-hydroxylase deficiency", "page": 207, "q": "Low aldosterone in 21-OH deficiency causes —", "opts": ["Hypokalemia", "Decreased BP", "Increased BP", "Hypernatremia"], "ans": 1, "exp": "Low aldosterone → decreased BP (with salt wasting and shock). (Book p207)", "type": "mcq"},
 {"id": "PEDS-C44-102", "sec": "21-hydroxylase deficiency", "page": 207, "q": "Hyponatremia in 21-OH deficiency is due to —", "opts": ["Dilutional excess water only", "Adrenal haemorrhage", "Salt wasting in urine", "Excess sodium intake"], "ans": 2, "exp": "In renal tubules: hyponatremia (salt wasting in urine). (Book p207)", "type": "mcq"},
 {"id": "PEDS-C44-103", "sec": "21-hydroxylase deficiency", "page": 207, "q": "The life-threatening consequence of salt wasting in 21-OH deficiency is —", "opts": ["Stroke", "Renal failure", "Heart failure", "Shock"], "ans": 3, "exp": "Low aldosterone → decreased BP, salt wasting → shock. (Book p207)", "type": "mcq"},
 {"id": "PEDS-C44-104", "sec": "21-hydroxylase deficiency", "page": 207, "q": "Hyperkalemia in 21-OH deficiency follows decreased renal —", "opts": ["Reabsorption/sodium-potassium exchange", "Blood flow", "Ammonia excretion", "Bicarbonate generation"], "ans": 0, "exp": "Hyperkalemia d/t decreased reabsorption (loss of aldosterone action on renal tubular exchange). (Book p207)", "type": "mcq"},
 {"id": "PEDS-C44-105", "sec": "21-hydroxylase deficiency", "page": 207, "q": "High androgens in 21-OH deficiency cause precocious puberty in —", "opts": ["Neither", "Males", "Females", "Both equally"], "ans": 1, "exp": "High androgens: in males — precocious puberty. (Book p207)", "type": "mcq"},
